const spacesEl=document.querySelector('#spaces');
const freeCount=document.querySelector('#free-count');
const occupiedCount=document.querySelector('#occupied-count');
const dialog=document.querySelector('#park-dialog');
const plateInput=document.querySelector('#plate-input');
const form=document.querySelector('#park-form');
const formError=document.querySelector('#form-error');
const searchInput=document.querySelector('#plate-search');
const searchStatus=document.querySelector('#search-status');
const clearSearch=document.querySelector('#clear-search');
const cars=Array(12).fill(null);
let selectedSpace=-1;

for(let i=0;i<cars.length;i++){
  const button=document.createElement('button');
  button.type='button';
  button.className='space';
  button.dataset.index=i;
  button.setAttribute('aria-label',`Space ${i+1}, free`);
  button.innerHTML=`<span class="space-number">${String(i+1).padStart(2,'0')}</span><span class="car" aria-hidden="true"></span><span class="plate-label"></span>`;
  button.addEventListener('click',()=>{
    if(cars[i]){
      const plate=cars[i];
      if(window.confirm(`Remove ${plate} from space ${i+1}?`)){
        cars[i]=null;
        render();
      }
    }else{
      selectedSpace=i;
      document.querySelector('#dialog-space').textContent=String(i+1).padStart(2,'0');
      plateInput.value='';
      formError.textContent='';
      dialog.showModal();
      plateInput.focus();
    }
  });
  spacesEl.append(button);
}

function render(){
  let occupied=0;
  [...spacesEl.children].forEach((button,i)=>{
    const plate=cars[i];
    const label=button.querySelector('.plate-label');
    button.classList.toggle('occupied',Boolean(plate));
    label.textContent=plate||'';
    button.setAttribute('aria-label',`Space ${i+1}, ${plate?`occupied by ${plate}`:'free'}`);
    if(plate)occupied++;
  });
  occupiedCount.textContent=occupied;
  freeCount.textContent=cars.length-occupied;
  updateSearch();
}

function updateSearch(){
  const query=searchInput.value.trim().toUpperCase();
  let matches=0;
  [...spacesEl.children].forEach((button,i)=>{
    button.classList.remove('match','no-match');
    if(query&&cars[i]){
      if(cars[i].includes(query)){
        button.classList.add('match');
        matches++;
      }else button.classList.add('no-match');
    }
  });
  clearSearch.classList.toggle('visible',Boolean(searchInput.value));
  searchStatus.textContent=query?(matches?`${matches} matching ${matches===1?'plate':'plates'} highlighted.`:'No matching plates found.'):'Search highlights matching plates.';
}

form.addEventListener('submit',event=>{
  event.preventDefault();
  const plate=plateInput.value.trim().replace(/\s+/g,' ').toUpperCase();
  if(!plate){formError.textContent='Enter a license plate to continue.';return;}
  if(cars.some((value,i)=>i!==selectedSpace&&value===plate)){
    formError.textContent='That plate is already parked.';
    plateInput.focus();
    return;
  }
  cars[selectedSpace]=plate;
  dialog.close();
  render();
});

document.querySelector('#cancel-park').addEventListener('click',()=>dialog.close());
dialog.addEventListener('close',()=>{selectedSpace=-1;formError.textContent='';});
searchInput.addEventListener('input',updateSearch);
clearSearch.addEventListener('click',()=>{searchInput.value='';updateSearch();searchInput.focus();});
render();
